<?php
declare(strict_types=1);

function avdCount(PDO $db,string $sql,array $p=[]):int{try{$q=$db->prepare($sql);$q->execute($p);return(int)$q->fetchColumn();}catch(Throwable){return 0;}}
function avdRows(PDO $db,string $sql,array $p=[]):array{try{$q=$db->prepare($sql);$q->execute($p);return$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){return[];}}

$exists=false;
try{$q=$db->prepare("SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='smarttoolz_download_activity' LIMIT 1");$q->execute();$exists=(bool)$q->fetchColumn();}catch(Throwable){}

$total=$today=$guest=$logged=$tools=$week=$month=0;$rows=[];$toolBreakdown=[];
if($exists){
$total=avdCount($db,'SELECT COUNT(*) FROM smarttoolz_download_activity');
$today=avdCount($db,'SELECT COUNT(*) FROM smarttoolz_download_activity WHERE downloaded_at>=CURDATE()');
$week=avdCount($db,'SELECT COUNT(*) FROM smarttoolz_download_activity WHERE downloaded_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)');
$month=avdCount($db,'SELECT COUNT(*) FROM smarttoolz_download_activity WHERE downloaded_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)');
$guest=avdCount($db,'SELECT COUNT(*) FROM smarttoolz_download_activity WHERE user_id IS NULL');
$logged=avdCount($db,'SELECT COUNT(*) FROM smarttoolz_download_activity WHERE user_id IS NOT NULL');
$tools=avdCount($db,'SELECT COUNT(DISTINCT tool_slug) FROM smarttoolz_download_activity');
$rows=avdRows($db,'SELECT id,user_id,guest_id,tool_slug,page_url,ip_address,user_agent,downloaded_at FROM smarttoolz_download_activity ORDER BY id DESC LIMIT 500');
$toolBreakdown=avdRows($db,'SELECT tool_slug,COUNT(*) total FROM smarttoolz_download_activity GROUP BY tool_slug ORDER BY total DESC LIMIT 20');
}
?>
