-size:10px;outline:none}.dl-empty{text-align:center;padding:24px;color:#8490a1;font-size:10px}@media(max-width:1100px){.dl-kpis{grid-template-columns:repeat(4,1fr)}.dl-grid{grid-template-columns:1fr}}@media(max-width:650px){.dl-kpis{grid-template-columns:repeat(2,1fr)}}
