<div class="dl-wrap">
<?php if(!$exists): ?><div class="dl-panel"><div class="dl-head"><div><h2>📥 Download Tracking</h2><p>The download activity table is not available yet.</p></div><span class="dl-tag g">MISSING</span></div><div class="dl-note">The expected table is <b>smarttoolz_download_activity</b>. Open the legacy tracking page once to install it automatically: <a href="/smart-toolz/admin/tracking.php" style="color:#635bff;font-weight:900">Initialize Download Tracking</a>.</div></div><?php else: ?>
<div class="dl-kpis"><div class="dl-kpi"><b><?=number_format($total)?></b><span>Total Downloads</span></div><div class="dl-kpi"><b><?=number_format($today)?></b><span>Today</span></div><div class="dl-kpi"><b><?=number_format($week)?></b><span>7 Days</span></div><div class="dl-kpi"><b><?=number_format($month)?></b><span>30 Days</span></div><div class="dl-kpi"><b><?=number_format($guest)?></b><span>Guest</span></div><div class="dl-kpi"><b><?=number_format($logged)?></b><span>Logged-in</span></div><div class="dl-kpi"><b><?=number_format($tools)?></b><span>Tools</span></div></div>
<div class="dl-grid"><section class="dl-panel"><div class="dl-head"><div><h2>Download Activity</h2><p>Latest 500 records · complete tracking details</p></div><span class="dl-tag u">LIVE TABLE</span></div><div class="dl-search"><input id="dlSearch" type="search" placeholder="Search user, guest, tool, page, IP, browser…"></div><div class="dl-table"><table id="dlTable"><thead><tr><th>ID</th><th>User / Guest</th><th>Tool</th><th>Page URL</th><th>IP</th><th>User Agent</th><th>Date / Time</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=av4h($r['id'])?></td><td><?php if(!empty($r['user_id'])): ?><span class="dl-tag u">User #<?=av4h($r['user_id'])?></span><?php elseif(!empty($r['guest_id'])): ?><span class="dl-tag g">Guest <?=av4h(substr((string)$r['guest_id'],0,18))?>…</span><?php else: ?>Unknown<?php endif; ?></td><td><?=av4h($r['tool_slug'])?></td><td class="dl-url"><?=av4h($r['page_url'])?></td><td><?=av4h($r['ip_address'])?></td><td class="dl-ua"><?=av4h($r['user_agent'])?></td><td><?=av4h($r['downloaded_at'])?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="dl-empty">No downloads recorded yet.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="dl-panel"><div class="dl-head"><div><h2>Downloads by Tool</h2><p>All-time tool ranking</p></div></div><?php $mx=max(1,(int)($toolBreakdown[0]['total']??1)); foreach($toolBreakdown as $r): ?><div class="dl-bar"><span><?=av4h($r['tool_slug'])?></span><div class="dl-track"><div class="dl-fill" style="width:<?=min(100,(int)round(((int)$r['total']/$mx)*100))?>%"></div></div><div class="dl-num"><?=number_format((int)$r['total'])?></div></div><?php endforeach; if(!$toolBreakdown): ?><div class="dl-empty">No tool download data.</div><?php endif; ?></section></div>
<?php endif; ?>
</div>
<script>(function(){const q=document.getElementById('dlSearch');const t=document.getElementById('dlTable');if(q&&t){q.addEventListener('input',()=>{const s=q.value.toLowerCase();t.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(s)?'':'none')})}})();</script>
